import { View, ScrollView } from 'react-native'
import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { AssistantMessage } from '../chat/components/AssistantMessage'
import { Block } from '../chat/utils/types'

export const DetailedSteps = ({
	collapsedData
}: {
	collapsedData: Block[]
}) => {
	const { theme } = useTheme()

	return (
		<View style={styles.modalContainer(theme)}>
			<View style={styles.modalGestureIndicator(theme)} />
			<ScrollView
				style={styles.scrollViewContainer}
				contentContainerStyle={styles.contentContainer}
				showsVerticalScrollIndicator={false}
				showsHorizontalScrollIndicator={false}
			>
				{collapsedData.map((block: any, index: number) => {
					return (
						<AssistantMessage
							key={index}
							messageId={''}
							block={block}
							isGenerating={false}
							isLastBlock={false}
							shouldAnimate={false}
							isOnlyBlock={true}
							isLauncher={false} // check is only for summary block to be pressable
						/>
					)
				})}
			</ScrollView>
		</View>
	)
}

const styles = defineStyles({
	modalGestureIndicator: (theme: Theme) => ({
		position: 'absolute',
		top: 20,
		alignSelf: 'center',
		width: 42,
		height: 4,
		borderRadius: 50,
		backgroundColor: colors[theme].gray[400]
	}),
	modalContainer: (theme: Theme) => ({
		flex: 1,
		backgroundColor: colors[theme].gray[25]
	}),
	scrollViewContainer: {
		flex: 1,
		marginTop: 60,
		marginHorizontal: 20
	},
	contentContainer: {
		paddingBottom: 20,
		gap: 20
	}
})
